// Audio-only download for YouTube Music tracks: the song, not a video of its
// cover art.
//
// A track YouTube Music publishes is an "Art Track" — the audio over one still
// image, uploaded by an auto-generated "<artist> - Topic" channel. The player
// response marks it `videoDetails.musicVideoType: MUSIC_VIDEO_TYPE_ATV`; the
// channel suffix and the "Auto-generated by YouTube." description footer are
// the fallbacks for the Invidious path, which does not pass that field on.
//
// The audio is YouTube's own Opus stream, passed through into Ogg (Ogg Opus,
// RFC 7845) without re-encoding, tagged from the description YouTube writes for
// these tracks. Only when no Opus stream exists is the AAC one written as m4a,
// since AAC cannot go into Ogg without a re-encode.
//
// YouTube Music's square cover art (at its original size) and its lyrics go in
// too — METADATA_BLOCK_PICTURE and LYRICS comments in Ogg. Both are extras: a
// track without them, or a failed request for them, still saves.
//
// The file is named `.opus`, RFC 7845's extension for Ogg Opus, not `.ogg`: KDE
// (Elisa, Dolphin) types a `.ogg` by its name as audio/ogg, which KFileMetaData
// hands to TagLib's Vorbis reader, so it saw no title, cover or lyrics at all in
// these files (白い熊, 2026-10-23). By `.opus` it is audio/x-opus+ogg and read in full.

import {
  ALL_FORMATS,
  BlobSource,
  EncodedAudioPacketSource,
  EncodedPacketSink,
  Input,
  Mp4OutputFormat,
  OggOutputFormat,
  Output,
  StreamTarget
} from 'mediabunny'

import { fetchRangedBlob } from './ranged-download'
import { getLocalMusicTrackExtras } from './api/local'
import { openSabrDownload } from './download-sabr'
// a cycle (download-common hands music tracks to this module), but only ever
// used at call time, by which point both modules have loaded
import { VideoDownloadError, guardSink, isComplete } from './download-common'

const WRITE_CHUNK_SIZE = 4 * 1024 * 1024

// an audio track is tens of megabytes; this only guards against a bad answer
const MAX_AUDIO_BYTES = 300 * 1024 * 1024

const TOPIC_SUFFIX = ' - Topic'

// an original-size cover is 1–3 MB at most; anything bigger is not a cover
const MAX_COVER_BYTES = 10 * 1024 * 1024

/**
 * @param {object} input
 * @param {string | null} [input.musicVideoType] `videoDetails.musicVideoType` from the player response
 * @param {string} [input.channel]
 * @param {string} [input.description]
 */
export function isMusicTrack({ musicVideoType, channel, description }) {
  if (musicVideoType) { return musicVideoType === 'MUSIC_VIDEO_TYPE_ATV' }

  return (channel ?? '').endsWith(TOPIC_SUFFIX) ||
    (/^Provided to YouTube by /.test(description ?? '') && /Auto-generated by YouTube\.\s*$/.test(description ?? ''))
}

/**
 * Tags from the description YouTube writes for an Art Track:
 *
 *   Provided to YouTube by <label>
 *
 *   <title> · <artist> · <artist>
 *
 *   <album>
 *
 *   ℗ 1990 <label>
 *
 *   Released on: 1990-01-01
 *   …
 *   Auto-generated by YouTube.
 * @param {object} input
 * @param {string} input.title
 * @param {string} input.channel
 * @param {string} [input.description]
 * @returns {{ title: string, artist: string, album?: string, date?: Date, raw?: { DATE: string } }}
 */
export function parseMusicTags({ title, channel, description }) {
  const tags = {
    title,
    artist: channel.endsWith(TOPIC_SUFFIX) ? channel.slice(0, -TOPIC_SUFFIX.length) : channel
  }

  const blocks = (description ?? '').split(/\n\s*\n/).map((block) => block.trim())
  if (!blocks[0]?.startsWith('Provided to YouTube by ')) { return tags }

  const credits = blocks[1]?.split(' · ').map((part) => part.trim()).filter((part) => part !== '') ?? []
  if (credits.length >= 2) {
    tags.title = credits[0]
    tags.artist = credits.slice(1).join(', ')
  }

  // the album block comes straight after the credits, unless the track has none
  const album = blocks[2]
  if (album && !album.includes('\n') && !/^(℗|©|Released on:)/.test(album)) {
    tags.album = album
  }

  const released = /^Released on: (\d{4})-(\d{2})-(\d{2})$/m.exec(description)
  if (released) {
    tags.date = new Date(Date.UTC(Number(released[1]), Number(released[2]) - 1, Number(released[3])))
  } else {
    // only the year is known: written as it is, not as a made-up 1 January
    const year = /^℗ (\d{4})\b/m.exec(description)
    if (year) { tags.raw = { DATE: year[1] } }
  }

  return tags
}

/**
 * @param {string} mimeType
 */
function isOpus(mimeType) {
  return (mimeType ?? '').startsWith('audio/') && (mimeType ?? '').includes('opus')
}

/**
 * Passthrough remux of one audio track into Ogg (Opus) or m4a (anything else).
 * @param {object} input
 * @param {Input} input.audioInput
 * @param {import('./download-mux').DownloadSink} input.sink
 * @param {object} input.tags mediabunny MetadataTags
 * @param {number} [input.durationSeconds]
 * @param {(fraction: number) => void} [input.onProgress]
 * @returns {Promise<{ endSeconds: number }>}
 */
async function muxAudio({ audioInput, sink, tags, durationSeconds, onProgress }) {
  const track = await audioInput.getPrimaryAudioTrack()
  if (track === null) {
    throw new Error('no audio track in the downloaded stream')
  }

  const target = new StreamTarget(new WritableStream({
    write: (chunk) => sink.write(chunk.position, chunk.data)
  }), { chunked: true, chunkSize: WRITE_CHUNK_SIZE })

  const output = new Output({
    format: track.codec === 'opus' ? new OggOutputFormat() : new Mp4OutputFormat(),
    target
  })

  const source = new EncodedAudioPacketSource(track.codec)
  output.addAudioTrack(source)
  output.setMetadataTags(tags)

  await output.start()

  const packetSink = new EncodedPacketSink(track)
  const decoderConfig = await track.getDecoderConfig()
  let packet = await packetSink.getFirstPacket()
  // same as the mkv path: neither container takes negative timestamps
  const shift = packet !== null ? Math.max(0, -packet.timestamp) : 0
  let first = true
  let endSeconds = 0
  let lastReportedFraction = 0

  try {
    while (packet !== null) {
      await source.add(shift > 0 ? packet.clone({ timestamp: packet.timestamp + shift }) : packet,
        first ? { decoderConfig } : undefined)
      first = false
      endSeconds = Math.max(endSeconds, packet.timestamp + packet.duration)

      if (durationSeconds > 0 && onProgress) {
        const fraction = Math.min(1, packet.timestamp / durationSeconds)
        if (fraction - lastReportedFraction >= 0.02) {
          lastReportedFraction = fraction
          onProgress(fraction)
        }
      }

      packet = await packetSink.getNextPacket(packet)
    }

    await output.finalize()
  } catch (error) {
    await output.cancel().catch(() => {})
    throw error
  }

  onProgress?.(1)
  return { endSeconds }
}

/**
 * @param {string} url
 * @returns {Promise<{ data: Uint8Array, mimeType: string } | null>}
 */
async function fetchImage(url) {
  const response = await fetch(url)
  if (!response.ok) { return null }

  const mimeType = (response.headers.get('Content-Type') ?? '').split(';')[0].trim()
  const data = new Uint8Array(await response.arrayBuffer())
  if (data.byteLength === 0 || data.byteLength > MAX_COVER_BYTES) { return null }

  return { data, mimeType: mimeType.startsWith('image/') ? mimeType : 'image/jpeg' }
}

/**
 * An Art Track's video frame is its cover, centred on a 16:9 canvas between two
 * bars, so the centre square of the thumbnail is the cover — the fallback when
 * YouTube Music did not name the cover itself.
 * @param {string} videoId
 * @returns {Promise<{ data: Uint8Array, mimeType: string } | null>}
 */
async function coverFromThumbnail(videoId) {
  const image = await fetchImage(`https://i.ytimg.com/vi/${videoId}/maxresdefault.jpg`)
  if (image === null) { return null }

  const bitmap = await createImageBitmap(new Blob([image.data], { type: image.mimeType }))
  const side = Math.min(bitmap.width, bitmap.height)
  const canvas = new OffscreenCanvas(side, side)
  canvas.getContext('2d').drawImage(bitmap, (bitmap.width - side) / 2, (bitmap.height - side) / 2, side, side, 0, 0, side, side)
  bitmap.close()

  const blob = await canvas.convertToBlob({ type: 'image/jpeg', quality: 0.92 })
  return { data: new Uint8Array(await blob.arrayBuffer()), mimeType: 'image/jpeg' }
}

/**
 * The cover art and lyrics, as MetadataTags fields.
 * @param {string} videoId
 * @returns {Promise<{ images?: object[], lyrics?: string }>}
 */
export async function fetchMusicExtras(videoId) {
  const extras = {}

  let coverUrl = null
  try {
    const { coverUrl: url, lyrics } = await getLocalMusicTrackExtras(videoId)
    coverUrl = url
    if (lyrics) { extras.lyrics = lyrics }
  } catch (error) {
    console.error('YouTube Music track details failed; saving without lyrics', error)
  }

  let cover = null
  try {
    cover = coverUrl ? await fetchImage(coverUrl) : null
  } catch (error) {
    console.error('fetching the cover art failed', error)
  }
  if (cover === null) {
    try {
      cover = await coverFromThumbnail(videoId)
    } catch (error) {
      console.error('cutting the cover art from the thumbnail failed; saving without one', error)
    }
  }
  if (cover !== null) {
    extras.images = [{ ...cover, kind: 'coverFront' }]
  }

  return extras
}

/**
 * The audio stream to fetch over the ranged-URL path: Opus first, then the
 * highest bitrate.
 * @param {object[]} adaptiveFormats local adaptive formats
 */
function pickUrlAudio(adaptiveFormats) {
  return (adaptiveFormats ?? [])
    .filter((format) => format.url && (format.mimeType ?? '').startsWith('audio/'))
    .filter((format) => !format.isDrc && !format.isDubbed && !format.isAutoDubbed && !format.isDescriptive)
    .sort((a, b) =>
      Number(isOpus(b.mimeType)) - Number(isOpus(a.mimeType)) ||
      (Number(b.bitrate) || 0) - (Number(a.bitrate) || 0)
    )[0] ?? null
}

/**
 * Downloads the audio alone and writes it as Ogg Opus (m4a without Opus),
 * trying SABR and then the direct URL — the same order as the video download.
 * @param {object} input
 * @param {object[]} [input.adaptiveFormats]
 * @param {object | null} [input.sabrData]
 * @param {import('./download-sabr').DownloadSabrFormat[]} [input.sabrFormats]
 * @param {string} input.videoId for the cover art and lyrics
 * @param {object} input.tags
 * @param {(resolution: string, ext: string) => Promise<import('./download-mux').DownloadSink>} input.openSink
 * @param {(stage: 'downloading' | 'muxing' | 'writing', fraction: number, detail?: { received: number, total: number }) => void} [input.onProgress]
 * @param {AbortSignal} [input.signal]
 * @returns {Promise<{ location: string, resolution: string, source: string, failedSubtitles: string[] }>}
 */
export async function runMusicDownload({
  adaptiveFormats,
  sabrData = null,
  sabrFormats = [],
  videoId,
  tags,
  openSink,
  onProgress,
  signal
}) {
  let lastError = null

  // fetched alongside the audio; the muxer needs them before it writes the header
  const extrasPromise = fetchMusicExtras(videoId)

  const muxInto = async (codecIsOpus, audioInput, durationSeconds, muxProgress) => {
    const extras = await extrasPromise
    const sink = guardSink(await openSink('', codecIsOpus ? 'opus' : 'm4a'))

    try {
      const { endSeconds } = await muxAudio({ audioInput, sink, tags: { ...tags, ...extras }, durationSeconds, onProgress: muxProgress })

      if (signal?.aborted) { throw new VideoDownloadError('canceled') }
      if (!isComplete(endSeconds, durationSeconds)) {
        throw new Error(`stream ended early: ${endSeconds.toFixed(1)} of ${durationSeconds.toFixed(1)} s`)
      }

      onProgress?.('writing', 0)
      const location = await sink.finish()
      onProgress?.('writing', 1)
      return location
    } catch (error) {
      await sink.abort().catch((abortError) => console.error('removing the partial download failed', abortError))

      if (sink.writeError !== null) {
        throw new VideoDownloadError('write-failed', String(sink.writeError))
      }
      throw error
    }
  }

  // 1. SABR, audio track only
  const sabrOpus = sabrFormats.filter((format) => isOpus(format.mimeType))
  if (sabrData && sabrFormats.length > 0) {
    let session = null
    const onAbort = () => session?.abort()
    signal?.addEventListener('abort', onAbort)

    try {
      let total = 0
      session = await openSabrDownload({
        sabrData,
        formats: sabrFormats,
        audioOnly: true,
        audioPool: sabrOpus.length > 0 ? sabrOpus : undefined,
        onBytes: (received) => {
          onProgress?.('downloading', total > 0 ? Math.min(1, received / total) : 0, { received, total })
        }
      })
      total = session.totalBytes
      if (signal?.aborted) { session.abort() }

      const location = await muxInto(isOpus(session.audio.mimeType), session.audioInput, session.durationSeconds)
      return { location, resolution: '', source: 'SABR audio', failedSubtitles: [] }
    } catch (error) {
      session?.abort()
      if (signal?.aborted) { throw new VideoDownloadError('canceled') }
      if (error instanceof VideoDownloadError) { throw error }

      console.error('SABR audio download failed, trying the direct stream URL', error)
      lastError = error
    } finally {
      signal?.removeEventListener('abort', onAbort)
    }
  }

  // 2. the direct audio URL, fetched into memory
  const format = pickUrlAudio(adaptiveFormats)
  if (format === null) {
    throw lastError === null
      ? new VideoDownloadError('no-format')
      : new VideoDownloadError('download-failed', String(lastError))
  }

  try {
    const blob = await fetchRangedBlob(format.url, {
      maxBytes: MAX_AUDIO_BYTES,
      signal,
      tooLargeError: () => new VideoDownloadError('video-too-large'),
      onProgress: (received, total) => {
        onProgress?.('downloading', total > 0 ? Math.min(1, received / total) : 0, { received, total: total > 0 ? total : 0 })
      }
    })
    onProgress?.('downloading', 1)

    const audioInput = new Input({ formats: ALL_FORMATS, source: new BlobSource(blob) })
    const location = await muxInto(isOpus(format.mimeType), audioInput, await audioInput.computeDuration(),
      (fraction) => onProgress?.('muxing', fraction))

    return { location, resolution: '', source: 'local adaptive audio', failedSubtitles: [] }
  } catch (error) {
    if (error instanceof VideoDownloadError) { throw error }
    if (signal?.aborted) { throw new VideoDownloadError('canceled') }
    throw new VideoDownloadError('download-failed', String(error))
  }
}
